import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../lib/supabase';
import toast from 'react-hot-toast';
import {
  Clock, Store, Shield, AlertTriangle, CheckCircle,
  CreditCard, ClipboardPaste, Building2
} from 'lucide-react';

const PRICING = [
  { minStores: 1, maxStores: 1, monthly: 150, label: '1 Store' },
  { minStores: 2, maxStores: 2, monthly: 250, label: '2 Stores' },
  { minStores: 3, maxStores: 3, monthly: 580, label: '3 Stores' },
];

export default function Settings() {
  const {
    staff, storeId, availableStores, subscriptionStatus, trialDaysLeft,
    isLocked, checkSubscription
  } = useAuth();

  const [subscriptionEnd, setSubscriptionEnd] = useState(null);
  const [now, setNow] = useState(new Date());
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [smsText, setSmsText] = useState('');
  const [verifying, setVerifying] = useState(false);
  const [billingCycle, setBillingCycle] = useState('monthly'); // 'monthly' or 'annual'

  const [form, setForm] = useState({
    business_mobile_money_number: '',
    local_currency: 'ZMW',
  });

  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (!storeId) return;
    const load = async () => {
      if (availableStores?.length > 0) {
        const end = availableStores[0]?.subscription_end_date;
        setSubscriptionEnd(end ? new Date(end) : null);
      }
      const { data } = await supabase
        .from('company_settings')
        .select('business_mobile_money_number, local_currency')
        .eq('store_id', storeId)
        .single();
      if (data) setForm({ business_mobile_money_number: data.business_mobile_money_number || '', local_currency: data.local_currency || 'ZMW' });
    };
    load();
  }, [availableStores, storeId]);

  const storeCount = availableStores?.length || 0;
  const plan = PRICING.find(p => storeCount >= p.minStores && storeCount <= p.maxStores) || null;
  const monthlyPrice = plan?.monthly || 0;
  const annualPrice = monthlyPrice * 10;
  const paymentAmount = billingCycle === 'monthly' ? monthlyPrice : annualPrice;
  const currency = form.local_currency || 'ZMW';
  const businessNumber = form.business_mobile_money_number || '097XXXXXXX';

  const formatTimeLeft = (endDate) => {
    const diff = endDate - now;
    if (diff <= 0) return { expired: true, text: 'Expired' };
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    return { expired: false, text: `${days}d ${hours}h remaining` };
  };

  const timeLeftInfo = subscriptionEnd ? formatTimeLeft(subscriptionEnd) : null;

  const handlePaste = async () => {
    try {
      setSmsText(await navigator.clipboard.readText());
      toast.success('Pasted');
    } catch {
      toast.error('Cannot access clipboard');
    }
  };

  const extractSmsDetails = (text) => {
    const patterns = {
      transactionId: [
        /Txn\.?\s*ID\s*[:\-]?\s*([A-Z0-9.]+)/i,
        /Transaction\s*ID\s*[:\-]?\s*([A-Z0-9.]+)/i,
        /Trans\s*ID\s*[:\-]?\s*([A-Z0-9.]+)/i,
        /Ref\s*[:\-]?\s*([A-Z0-9.]+)/i,
      ],
      amount: [
        /Amount\s*[:\-]?\s*([\d,]+\.?\d*)/i,
        /ZMW\s*([\d,]+\.?\d*)/i,
        /K\s*([\d,]+\.?\d*)/i,
      ],
      senderName: [
        /from\s+([A-Za-z\s]+?)(?:\s+on|\s+at|\s+\.|\s+Ref|\s*$)/i,
      ],
      senderPhone: [
        /from\s+(\d{10,})/i,
        /(\d{10,})/,
      ],
    };
    let transactionId = null, amount = null, senderName = null, senderPhone = null;
    for (const regex of patterns.transactionId) {
      const m = text.match(regex);
      if (m) { transactionId = m[1].trim(); break; }
    }
    for (const regex of patterns.amount) {
      const m = text.match(regex);
      if (m) { amount = parseFloat(m[1].replace(/,/g, '')); break; }
    }
    for (const regex of patterns.senderName) {
      const m = text.match(regex);
      if (m) { senderName = m[1].trim(); break; }
    }
    for (const regex of patterns.senderPhone) {
      const m = text.match(regex);
      if (m) { senderPhone = m[1].trim(); break; }
    }
    return { transactionId, amount, senderName, senderPhone };
  };

  const handleVerifyPayment = async (e) => {
    e.preventDefault();
    if (!smsText.trim()) return toast.error('Paste SMS');
    setVerifying(true);
    try {
      const { transactionId, amount, senderName } = extractSmsDetails(smsText);
      if (!transactionId) throw new Error('Transaction ID not found');
      if (!amount) throw new Error('Amount not found');
      if (amount < paymentAmount)
        throw new Error(`Amount too low (expected ${paymentAmount} ZMW)`);

      const { data, error } = await supabase
        .from('mobile_money_transactions')
        .select('*')
        .eq('transaction_id', transactionId)
        .eq('status', 'pending')
        .single();
      if (error || !data) throw new Error('Transaction not found or already used');
      if (Math.abs(data.amount - amount) > 0.01) throw new Error('Amount mismatch');
      if (senderName && data.sender_name && !data.sender_name.toLowerCase().includes(senderName.toLowerCase())) {
        throw new Error('Sender name mismatch');
      }
      await supabase.from('mobile_money_transactions').update({ status: 'used' }).eq('id', data.id);

      const storeIds = availableStores.map(s => s.id);
      const endDate = new Date();
      if (billingCycle === 'monthly') {
        endDate.setMonth(endDate.getMonth() + 1);
      } else {
        endDate.setMonth(endDate.getMonth() + 12);
      }

      const { error: updateError } = await supabase
        .from('stores')
        .update({
          subscription_status: 'active',
          subscription_end_date: endDate.toISOString(),
          subscription_plan: billingCycle,
          trial_started_at: null,
        })
        .in('id', storeIds);
      if (updateError) throw updateError;

      await checkSubscription(storeId);
      toast.success(`Subscription activated for ${billingCycle === 'monthly' ? '1 month' : '12 months'}!`);
      setShowPaymentModal(false);
      setSmsText('');
    } catch (err) {
      toast.error(err.message);
    } finally {
      setVerifying(false);
    }
  };

  const isAdmin = staff?.role === 'admin';
  if (!isAdmin) return <div className="p-8 text-red-600">Access Denied</div>;

  return (
    <div className="p-4 h-full overflow-y-auto max-w-2xl mx-auto">
      <h1 className="text-2xl font-bold mb-6 flex items-center gap-2">
        <Shield className="text-green-600" /> Subscription Details
      </h1>

      {storeCount === 0 ? (
        <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-6 text-center">
          <Store className="mx-auto mb-2 text-yellow-600" size={32} />
          <p className="text-lg font-medium text-yellow-800">No store created yet.</p>
          <p className="text-sm text-yellow-700 mt-1">Create a store to manage your subscription.</p>
        </div>
      ) : (
        <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-8 space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500 uppercase tracking-wide">Current Package</p>
              <h2 className="text-3xl font-bold text-gray-900 mt-1">{plan.label}</h2>
              {plan && (
                <p className="text-lg text-green-700 font-medium mt-1">
                  ZMW {plan.monthly} <span className="text-gray-500 text-sm">/ month</span>
                </p>
              )}
            </div>
            <Shield className="text-green-500" size={40} />
          </div>

          <div className="flex items-center gap-3">
            {subscriptionStatus === 'active' && (
              <>
                <CheckCircle className="text-green-600" size={24} />
                <span className="text-lg font-semibold text-green-700">Active</span>
              </>
            )}
            {subscriptionStatus === 'trialing' && (
              <>
                <Clock className="text-blue-600" size={24} />
                <span className="text-lg font-semibold text-blue-700">
                  Trial — {trialDaysLeft > 0 ? `${trialDaysLeft} day${trialDaysLeft > 1 ? 's' : ''} left` : 'Ended'}
                </span>
              </>
            )}
            {subscriptionStatus === 'expired' && (
              <>
                <AlertTriangle className="text-red-600" size={24} />
                <span className="text-lg font-semibold text-red-700">Expired</span>
              </>
            )}
            {subscriptionStatus === 'pending' && (
              <>
                <Clock className="text-yellow-600" size={24} />
                <span className="text-lg font-semibold text-yellow-700">Pending</span>
              </>
            )}
          </div>

          {subscriptionStatus === 'active' && timeLeftInfo && (
            <div className="bg-green-50 border border-green-200 rounded-lg p-4">
              <div className="flex items-center gap-2">
                <Clock className="text-green-600" size={20} />
                <span className="font-medium text-green-800">
                  {timeLeftInfo.expired ? 'Expired' : timeLeftInfo.text}
                </span>
              </div>
              {subscriptionEnd && (
                <p className="text-sm text-green-700 mt-1">
                  Expires on: {subscriptionEnd.toLocaleDateString('en-ZM', {
                    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
                  })}
                </p>
              )}
            </div>
          )}

          {isLocked && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 flex items-center gap-2">
              <AlertTriangle className="text-red-600" size={20} />
              <span className="font-medium text-red-700">Access restricted — subscription required.</span>
            </div>
          )}

          <button
            onClick={() => setShowPaymentModal(true)}
            className="w-full bg-green-600 text-white py-3 rounded-lg font-medium flex items-center justify-center gap-2 hover:bg-green-700"
          >
            <CreditCard size={20} /> {subscriptionStatus === 'active' ? 'Renew / Upgrade' : 'Subscribe Now'}
          </button>

          <div className="border-t pt-4">
            <p className="text-sm text-gray-500 mb-2">Your Stores ({storeCount}):</p>
            <div className="flex flex-wrap gap-2">
              {availableStores.map(s => (
                <span key={s.id} className="px-3 py-1 rounded-full text-sm bg-gray-100 text-gray-800">
                  {s.name}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}

      {showPaymentModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-md">
            <div className="p-4 border-b"><h2 className="text-xl font-bold">Activate Subscription</h2></div>
            <div className="p-4 space-y-4">
              <div className="bg-blue-50 p-3 rounded">
                <p className="font-medium">Your Plan: {plan.label}</p>
                <p className="text-sm mt-1">Monthly: {currency} {monthlyPrice} | Annual: {currency} {annualPrice}</p>
              </div>

              {/* Billing Cycle Selection – Upgrade/Downgrade */}
              <div>
                <label className="block text-sm font-medium mb-2">Choose Billing Cycle</label>
                <div className="flex gap-4">
                  <label className="flex items-center gap-1 cursor-pointer">
                    <input
                      type="radio"
                      name="billingCycle"
                      value="monthly"
                      checked={billingCycle === 'monthly'}
                      onChange={() => setBillingCycle('monthly')}
                    />
                    <span>Monthly ({currency} {monthlyPrice})</span>
                  </label>
                  <label className="flex items-center gap-1 cursor-pointer">
                    <input
                      type="radio"
                      name="billingCycle"
                      value="annual"
                      checked={billingCycle === 'annual'}
                      onChange={() => setBillingCycle('annual')}
                    />
                    <span>Annual ({currency} {annualPrice})</span>
                  </label>
                </div>
              </div>

              <div className="bg-blue-50 p-3 rounded">
                <p className="font-medium">
                  Send <span className="text-xl font-bold">{currency} {paymentAmount}</span> to:
                </p>
                <p className="text-2xl font-bold mt-1">{businessNumber}</p>
                <p className="text-xs mt-2 text-gray-500">Use Airtel Money and keep the confirmation SMS.</p>
              </div>

              <textarea
                value={smsText}
                onChange={e => setSmsText(e.target.value)}
                rows={3}
                className="w-full p-2 border rounded font-mono text-sm"
                placeholder="Paste confirmation SMS here"
              />
              <div className="flex gap-2">
                <button onClick={handlePaste} className="px-3 py-1.5 bg-gray-200 rounded flex items-center gap-1">
                  <ClipboardPaste size={14} /> Paste
                </button>
                <button onClick={handleVerifyPayment} disabled={verifying} className="flex-1 bg-green-600 text-white py-1.5 rounded">
                  {verifying ? 'Verifying...' : 'Verify & Activate'}
                </button>
              </div>
            </div>
            <div className="p-3 border-t flex justify-end">
              <button onClick={() => setShowPaymentModal(false)} className="px-4 py-1.5 border rounded">Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
